    private void btnSALVARActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnSALVARActionPerformed
        String sqlInsert = """
                           INSERT INTO zelador(nome, especialidade, email, telefone)
                           VALUES(?,?,?,?)
                           """;
        
        try {
            Connection conex = Conexao.conectar();
            PreparedStatement stmt = conex.prepareStatement(sqlInsert);
            
            String nome = txtNome.getText();
            String especialidade = txtEspecialidade.getText();
            String email = txtEmail.getText();
            String telefone = txtTelefone.getText();
            
            stmt.setString(1, nome);
            stmt.setString(2, especialidade);
            stmt.setString(3, email);
            stmt.setString(4, telefone);
            
        int linhas = stmt.executeUpdate();
        if(linhas >0){
         JOptionPane.showMessageDialog(this, "Cadastro realizado com sucesso");
         
         txtNome.setText("");
         txtEspecialidade.setText("");
         txtEmail.setText("");
         txtTelefone.setText("");
         txtNome.requestFocus();
         
        }
   
        } catch (SQLException erro) {
            JOptionPane.showMessageDialog(this, "Nao foi possivel cadastrar - ERRO:" + erro);
        }
    }//GEN-LAST:event_btnSALVARActionPerformed

